with metrics as (select *, min(duration_sec) over w_part as last3_min_duration_sec, sum(duration_sec) over w_part as last3_sum_duration_sec, count(duration_sec) over w_part as last3_count_duration_sec from web_events window w_part as (partition by session_id order by event_time, id rows between 2 preceding and current row)) select id, event_type, duration_sec, last3_sum_duration_sec, last3_count_duration_sec, case when event_type rlike '^(click|search)$' then 'GROUP_A' when event_type rlike '^(page_view|add_to_cart)$' then 'EXTENDED' else 'GROUP_B' end as event_type_zone from metrics;
